    empathy_lines = [
        f"很多深圳出海企业一年在海外律师、平台投诉、取证翻译、品牌维护上投入不少资金，{label}结束后却只把材料放进档案柜。政策看不明白、费用票据散、申报窗口短，是企业最常见的三道坎；一步没跟上，最高200万元的资助机会就可能错过。",
        f"不少老板忙着订单、交付和海外客户，{label}处理完已经很累，根本没时间再研究申报指南。可海外维权本来就是高成本动作，判决、仲裁或和解材料如果齐全，就值得顺手做一次补贴测评。",
        f"出海不是只花市场费用，品牌被仿冒、专利被侵权、商标被抢注时，维权支出往往来得又急又重。{label}已经形成结果文件后，企业最该做的不是马上翻下一页工作，而是先把补贴可能性算清楚。",
        f"企业经营者最怕两件事：一是海外维权支出已经发生，二是政策窗口过去才发现本来可以申。{label}如果有清晰文书和支出凭证，现在就适合把材料拉出来做一轮体检。",
        f"很多深圳企业不是没有补贴机会，而是不知道自己的海外维权成本也能进入政策视野。{label}背后的律师费、翻译费、取证材料、服务合同和付款记录，整理好了才有机会变成申报支撑。",
        f"海外市场打下来不容易，守住品牌和技术更不容易。{label}背后常常是几个月甚至更久的沟通、举证和费用投入，如果只当成法务事项处理，补贴线索很容易被漏掉。",
        f"老板们都懂，海外纠纷一来，成本不是小数目；但真正麻烦的是材料分散在法务、财务、业务和外部律师手里。{label}想要申报顺利，第一步不是写长文，而是把证据链先拼起来。",
        f"做跨境电商、软件出海、海外专利布局的企业，最容易低估知识产权维权的后续价值。{label}处理完后，如果项目有结果、费用能证明、经验能总结，就可以先看看这项资助。",
        f"一年一次的窗口，错过就要等下一轮。{label}如果刚好发生在近三年，企业别只盯着案件结果，也要看它能不能和补贴申报、制度建设、出海合规一起规划。",
        f"海外维权不是谁都想碰，但已经投入了，就别让材料白白沉睡。{label}只要结果文书、费用凭证和制度基础能对上，就值得先做一次轻量筛查。",
    ]
